{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/hero-split-media.json
    What HeroSplit shows beside the text: a picture, a picture with a floating card, a grid of four pictures with captions, or a picture with two plan cards floating over it.
    Props (p): content, alt, media. *}
{var $v_content = ($p['content'] ?? null)}
{var $v_alt = ($p['alt'] ?? null)}
{var $v_media = ($p['media'] ?? 'picture')}
{if og_t(og_eq($v_media, 'picture'))}
  {=og_include('blocks/media-frame.latte', ['p' => ['alt' => $v_alt, 'ratio' => '4/3']])|noescape}
{/if}
{if og_t(og_eq($v_media, 'card'))}
  {=og_include('blocks/offer-media.latte', ['p' => ['alt' => $v_alt, 'card' => og_get($v_content, ['card'])]])|noescape}
{/if}
{if og_t(og_and([og_eq($v_media, 'grid'), og_gt(og_len(og_get($v_content, ['features'])), 0)]))}
  {capture $c_3}
    {foreach og_l(og_get($v_content, ['features'])) as $v_f}
      {var $v_i = $iterator->counter0}
      {if og_t(og_lt($v_i, 4))}
        {capture $c_2}
          {=og_include('blocks/media-frame.latte', ['p' => ['alt' => og_get($v_f, ['title']), 'ratio' => '1/1']])|noescape}
          {capture $c_1}
            {=og_text(og_get($v_f, ['title']))}
          {/capture}
          {=og_include('compose/Text.latte', ['size' => 'xs', 'class' => 'text-muted-foreground', 'children' => (string) $c_1])|noescape}
        {/capture}
        {=og_include('blocks/figure-block.latte', ['p' => ['className' => og_cnv(['flex flex-col gap-2']), 'testid' => 'hero-tile'], 'children' => og_markup($c_2)])|noescape}
      {/if}
    {/foreach}
  {/capture}
  {=og_include('compose/Box.latte', ['class' => 'grid grid-cols-2 gap-4', 'attrs' => og_attrs(['data-slot', 'hero-grid']), 'children' => (string) $c_3])|noescape}
{/if}
{if og_t(og_and([og_eq($v_media, 'plans'), og_gt(og_len(og_get($v_content, ['plans'])), 0)]))}
  {capture $c_8}
    {=og_include('blocks/media-frame.latte', ['p' => ['alt' => $v_alt, 'ratio' => '4/3']])|noescape}
    {foreach og_l(og_get($v_content, ['plans'])) as $v_p}
      {var $v_i = $iterator->counter0}
      {if og_t(og_lt($v_i, 2))}
        {capture $c_7}
          {capture $c_4}
            {=og_text(og_get($v_p, ['name']))}
          {/capture}
          {=og_include('compose/Text.latte', ['size' => 'sm', 'weight' => 'semibold', 'children' => (string) $c_4])|noescape}
          {capture $c_6}
            {=og_include('icons/LucideIcon.latte', ['name' => 'check', 'size' => 16])|noescape}
            {capture $c_5}
              {=og_text(og_get($v_p, ['tagline']))}
            {/capture}
            {=og_include('compose/Text.latte', ['size' => 'xs', 'class' => 'text-muted-foreground', 'children' => (string) $c_5])|noescape}
          {/capture}
          {=og_include('compose/Group.latte', ['gap' => '2', 'align' => 'center', 'children' => (string) $c_6])|noescape}
        {/capture}
        {=og_include('compose/Stack.latte', ['gap' => '2', 'class' => og_s(og_cnv(['absolute w-48 rounded bg-card p-4 shadow-lg', (og_t(og_eq($v_i, 0)) ? 'top-8 left-4' : 'right-4 bottom-8')])), 'attrs' => og_attrs(['data-slot', 'hero-plan']), 'children' => (string) $c_7])|noescape}
      {/if}
    {/foreach}
  {/capture}
  {=og_include('compose/Box.latte', ['class' => 'relative', 'attrs' => og_attrs(['data-slot', 'hero-media']), 'children' => (string) $c_8])|noescape}
{/if}
